(window.__qhadithX=window.__qhadithX||{})[89]={"25":[{"c":"Sunan Abu Dawud","r":"Hadith 4007","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4007","x":"The tradition mentioned above has also been transmitted by Hisham b. Sa'd with a different chain of narrators in a similar way.","ar":"حَدَّثَنَا جَعْفَرُ بْنُ مُسَافِرٍ، حَدَّثَنَا ابْنُ أَبِي فُدَيْكٍ، عَنْ هِشَامِ بْنِ سَعْدٍ، بِإِسْنَادِهِ مِثْلَهُ ‏.‏","v":[]},{"c":"Sunan Abu Dawud","r":"Hadith 4008","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4008","x":"Narrated 'Aishah:\n\nThe revelation came down to Messenger of Allah (ﷺ) and he recited to is: \"A surah which We have sent down and which We have ordained (faradnaha)\" Abu Dawud said: The letter ra (r) is the word faradnaha has short vowel a (with out doubling of consonant r), and then he reached the verses after this verse.","ar":"حَدَّثَنَا مُوسَى بْنُ إِسْمَاعِيلَ، حَدَّثَنَا حَمَّادٌ، حَدَّثَنَا هِشَامُ بْنُ عُرْوَةَ، عَنْ عُرْوَةَ، أَنَّ عَائِشَةَ، - رضى الله عنها - قَالَتْ نَزَلَ الْوَحْىُ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فَقَرَأَ عَلَيْنَا ‏{‏ سُورَةٌ أَنْزَلْنَاهَا وَفَرَضْنَاهَا ‏}‏ ‏.‏ قَالَ أَبُو دَاوُدَ يَعْنِي مُخَفَّفَةً حَتَّى أَتَى عَلَى هَذِهِ الآيَاتِ ‏.‏","v":[]}],"26":[{"c":"Sunan Abu Dawud","r":"Hadith 4007","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-4007","x":"The tradition mentioned above has also been transmitted by Hisham b. Sa'd with a different chain of narrators in a similar way.","ar":"حَدَّثَنَا جَعْفَرُ بْنُ مُسَافِرٍ، حَدَّثَنَا ابْنُ أَبِي فُدَيْكٍ، عَنْ هِشَامِ بْنِ سَعْدٍ، بِإِسْنَادِهِ مِثْلَهُ ‏.‏","v":[]}]};